    "shortDescription": "Deck promise: Same content, half the slides, twice the dwell time: atomic cuts, CRAP discipline, no decoration.",
    "description": "Clean an internal deck as a top design-system maintainer actually cleans one — atomic structure, CRAP discipline, no decoration. A variable-length, 1920×1080 cleanup pass that takes a 40-80-slide content heap (RFCs, architecture reviews, ops decks pasted from docs and Slack) and returns an 18-35-slide readable deck, cutting 30-55% of slides through delete / merge / rewrite decisions. Three non-negotiable moves — every kept slide is named at one atomic level (atom / molecule / organism), every kept slide passes the four-question CRAP audit (Contrast / Repetition / Alignment / Proximity), and body text is held to 60-80 chars per line on a multiple-of-base-unit spacing grid. Best used for quarterly architecture reviews, RFC decks, ops decks, and any internal deck where a VP said \"I couldn't get past slide 9.\"",
